1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerFieldsException;
8	
9	/**
10	 * Normalizes an owner's optional {@code email}. When the body carries no email the step
11	 * does nothing, so email stays optional. When one is present it must be a syntactically
12	 * valid address, otherwise {@link InvalidOwnerFieldsException} yields a 400; a valid
13	 * address is lower-cased in place on the shared body so it is persisted and returned
14	 * lower-cased. It mutates the already-published body variable rather than binding
15	 * {@code @RequestBody}, so it composes after the sole binding step in each pipeline.
16	 */
17	public class NormalizeOwnerEmail {
18	
19	    public void service(@Val OwnerFieldsDto request) throws InvalidOwnerFieldsException {
20	        String email = request.getEmail();
21	        if (email == null || email.isBlank()) {
22	            return; // email is optional
23	        }
24	        if (!OwnerEmail.isValid(email)) {
25	            throw new InvalidOwnerFieldsException(List.of("email"));
26	        }
27	        request.setEmail(OwnerEmail.normalize(email));
28	    }
29	}
