1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerHouseholdException;
10	
11	/**
12	 * Runs in {@code POST /api/owners} after the telephone-uniqueness check, reading the
13	 * already-validated body as a variable. Rejects the request when another owner already
14	 * shares its lastName and address (compared case-insensitively with collapsed whitespace),
15	 * throwing {@link DuplicateOwnerHouseholdException} for a 409 before any entity is built or
16	 * persisted. A request that opts in with {@code sharesHousehold=true} is allowed through.
17	 */
18	public class EnsureUniqueOwnerHousehold {
19	
